 const load=col(9+s);
 const cr=[caseName,s,duration,s===0?1:`=F${r-1}+1`,`=E${r}+D${r}-1`,`=SUM('Команда'!${load}7:${load}19)`,`=SUMPRODUCT('Команда'!$H$7:$H$19,'Команда'!${load}7:${load}19)*${ref('teamFactor',p)}`,`=H${r}*${ref('teamCashShare',p)}`,`=H${r}-I${r}`,`=(SUMIFS('Прямые расходы'!$F$7:$F$18,'Прямые расходы'!$C$7:$C$18,C${r},'Прямые расходы'!$D$7:$D$18,"месяц")+SUMIFS('Прямые расходы'!$F$7:$F$18,'Прямые расходы'!$C$7:$C$18,C${r},'Прямые расходы'!$D$7:$D$18,"разово")/D${r})*(1+${ref('vat',p)}*(1-${ref('vatRecovery',p)}))`,`='Время участников'!K${r}`,`=(H${r}+K${r})*${ref('reserve',p)}`,`=I${r}+K${r}+(I${r}+K${r})*${ref('reserve',p)}`,`=SUM(H${r},K${r}:M${r})`,`=O${r}*D${r}`,s===0?`=P${r}`:`=Q${r-1}+P${r}`];cr.forEach((v,j)=>put('Стоимость Flicker',`${col(j+2)}${r}`,v));
