 const f={7:`=SUM(${cf(`R${a}:R${b}`)})`,8:`=SUM(${cf(`Q${a}:Q${b}`)})`,9:`=IF(OR(MAX(${cf(`O${a}:O${b}`)})<=0,MIN(${cf(`O${a}:O${b}`)})>=0),"не определена",(1+IRR(${cf(`O${a}:O${b}`)}))^12-1)`,10:`=IF(OR(MAX(${cf(`N${a}:N${b}`)})<=0,MIN(${cf(`N${a}:N${b}`)})>=0),"не определена",(1+IRR(${cf(`N${a}:N${b}`)}))^12-1)`,11:`=IF(MIN(${cf(`V${a}:V${b}`)})=999,"не окупается",MIN(${cf(`V${a}:V${b}`)}))`,12:`=IF(MIN(${cf(`W${a}:W${b}`)})=999,"не окупается",MIN(${cf(`W${a}:W${b}`)}))`,13:`='Удержание'!${c}23`,14:`='Стоимость Flicker'!O${op}*12`,15:`=${c}13-${c}14`,16:`=${c}15/${c}14`,17:`=SUM(${cf(`O${a}:O${b}`)})/(${totalCost})`,18:`=(${grossPV})/(${costPV})`,19:`=IF('Удержание'!${c}17<=0,"не применимо",${c}14/'Удержание'!${c}17)`,20:`=IF('Удержание'!${c}20<=0,"недостижимо",${c}14/'Удержание'!${c}20)`,21:`=IF(OR('Удержание'!${c}20<=0,'Удержание'!${c}15<=0),"недостижимо",${c}14/('Удержание'!${c}15*'Удержание'!${c}20))`,22:`=SUM('Стоимость Flicker'!P${st}:P${st+3})`,23:`='Стоимость Flicker'!P${st}`,24:`='Стоимость Flicker'!N${st}*'Стоимость Flicker'!D${st}`,25:`=${cf(`S${b}`)}`,26:`=${cf(`T${b}`)}`,27:`='Удержание'!${c}16`};Object.entries(f).forEach(([r,v])=>put('Сценарии',`${c}${r}`,v));
