  const drivers=[`=${tri(u(0),21)}`,`=${tri(u(1),22)}`,`=${tri(u(2),23)}`,`=${tri(u(3),24)}`,`=${tri(u(3),25)}`,`=$C$26+INT((${u(0)})*($E$26-$C$26+1))`,`=${tri(u(4),27)}`];
  drivers.forEach((v,i)=>put(n,`${col(i+2)}${r}`,v));
  for(const [c,q] of [['I','AS'],['J','AT'],['K','AU']])put(n,`${c}${r}`,`=$${q}$4/(1+H${r})^(1/12)`);
